const mockOrders = [
  { order_id: "DY4d5301", customer_email: "customer@example.com", status: "Shipped", item: "Blue Widget", eta: "2026-07-20" },
  { order_id: "AB1234", customer_email: "jane@email.com", status: "Processing", item: "Red Widget", eta: "2026-07-25" },
  { order_id: "CD5678", customer_email: "test@email.com", status: "Delivered", item: "Green Widget", eta: "2026-07-10" },
  { order_id: "J0n83024", customer_email: "customer@example.com", status: "Delivered", item: "Green Widget", eta: "2026-07-13" }
];

const query = $input.first().json.query || {};

if (!query.order_id && !query.email) {
  return [{ json: { error: "Please provide an order_id or email parameter" } }];
}

// If order_id is given, it's unique — return exactly that one order
if (query.order_id) {
  const match = mockOrders.find(o => o.order_id === query.order_id);
  return [{ json: match || { error: "Order not found" } }];
}

// If only email is given, there could be multiple orders — return ALL of them
const matches = mockOrders.filter(o => o.customer_email === query.email);

if (matches.length === 0) {
  return [{ json: { error: "No orders found for this email" } }];
}

return [{ json: { orders: matches, count: matches.length } }];
